<?php echo view('operations_approval\Views\partials\styles'); ?><div class="page-title clearfix"><h1><?php echo app_lang('operations_workflow_types'); ?></h1><div class="title-button-group"><?php echo anchor(get_uri('operations_workflows/edit'), '<i data-feather="plus-circle" class="icon-16"></i> ' . app_lang('add'), ['class' => 'btn btn-primary']); ?></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover"><thead><tr><th><?php echo app_lang('name'); ?></th><th><?php echo app_lang('operations_code'); ?></th><th><?php echo app_lang('status'); ?></th><th></th></tr></thead><tbody><?php foreach ($rows as $row) { ?><tr><td><?php echo esc($row->name); ?></td><td><?php echo esc($row->code); ?></td><td><span class="badge <?php echo $row->status === 'active' ? 'bg-success' : ($row->status === 'inactive' ? 'bg-secondary' : 'bg-warning'); ?>"><?php echo esc(ucfirst($row->status)); ?></span></td><td class="text-end"><?php echo anchor(get_uri('operations_workflows/edit/' . $row->id), app_lang('edit'), ['class' => 'btn btn-default btn-sm']); ?> <?php if ($row->status === 'draft') { echo form_open(get_uri('operations_workflows/publish/' . $row->id), ['class' => 'd-inline general-form']); ?><button class="btn btn-primary btn-sm"><?php echo app_lang('operations_publish'); ?></button><?php echo form_close(); } else { echo form_open(get_uri('operations_workflows/toggle-status/' . $row->id), ['class' => 'd-inline general-form']); ?><button class="btn <?php echo $row->status === 'active' ? 'btn-danger' : 'btn-success'; ?> btn-sm"><?php echo app_lang($row->status === 'active' ? 'operations_disable' : 'operations_enable'); ?></button><?php echo form_close(); } ?></td></tr><?php } ?></tbody></table></div></div>
<script>$(document).ready(function(){$('.general-form').appForm({isModal:false});});</script>
